'use server'

import { revalidatePath } from 'next/cache'

interface NotificationPreference {
  userId: string
  notificationsEnabled: boolean
}

// In-memory storage for demo purposes
// In a real application, this would be a database
let notificationPreferences: Record<string, NotificationPreference> = {
  'user-1': { userId: 'user-1', notificationsEnabled: true },
  'user-2': { userId: 'user-2', notificationsEnabled: false },
}

export async function toggleNotifications(userId: string) {
  'use server'

  // Toggle the notification preference
  const currentPreference = notificationPreferences[userId] || { userId, notificationsEnabled: false }
  const newPreference = !currentPreference.notificationsEnabled

  notificationPreferences[userId] = {
    ...currentPreference,
    notificationsEnabled: newPreference
  }

  // Revalidate the current page to trigger a refresh
  // This is Next.js's recommended approach for refreshing the current page
  revalidatePath('/')

  return {
    success: true,
    notificationsEnabled: newPreference
  }
}

export function getCurrentNotificationPreference(userId: string) {
  return notificationPreferences[userId]?.notificationsEnabled ?? false
}

