'use client'

import { useState } from 'react'
import { toggleNotifications } from '../actions/toggle-notifications'

interface NotificationToggleProps {
  userId: string
  initialPreference: boolean
}

export function NotificationToggle({ userId, initialPreference }: NotificationToggleProps) {
  const [notificationsEnabled, setNotificationsEnabled] = useState(initialPreference)

  const handleToggle = async () => {
    try {
      const result = await toggleNotifications(userId)
      if (result.success) {
        // The page will refresh automatically due to revalidatePath
        // We update local state immediately for better UX
        setNotificationsEnabled(result.notificationsEnabled)
      }
    } catch (error) {
      console.error('Failed to toggle notifications:', error)
    }
  }

  return (
    <div className="max-w-md mx-auto mt-8 p-6 bg-white rounded-lg shadow-md">
      <h2 className="text-xl font-semibold mb-4">Notification Preferences</h2>

      <div className="flex items-center justify-between">
        <div>
          <p className="font-medium">Email Notifications</p>
          <p className="text-sm text-gray-600">
            {notificationsEnabled 
              ? 'Currently enabled - you will receive notifications' 
              : 'Currently disabled - you will not receive notifications'
            }
          </p>
        </div>

        <button
          onClick={handleToggle}
          className={`relative inline-flex items-center h-6 rounded-full w-11 transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 ${
            notificationsEnabled ? 'bg-blue-600' : 'bg-gray-200'
          }`}
        >
          <span 
            className={`inline-block w-4 h-4 transform bg-white rounded-full transition-transform ${
              notificationsEnabled ? 'translate-x-6' : 'translate-x-1'
            }`}
          />
        </button>
      </div>

      <div className="mt-4 text-sm text-gray-500">
        After toggling, the page will refresh to show the updated preference.
      </div>
    </div>
  )
}

